// Package server exposes the frozen public surface of StackWeaver.
//
// The baseline only reports process health. Later work adds the capabilities
// described in README.md; keep the exported surface here backward compatible.
package server

import (
	"encoding/json"
	"net/http"
)

// Version is the baseline release identifier.
const Version = "0.1.0"

type health struct {
	Status  string `json:"status"`
	Service string `json:"service"`
	Version string `json:"version"`
}

// Handler returns the HTTP surface served by the baseline. It injects no
// Provider, so POST /v1/apply succeeds only for empty plans and answers 503
// provider_unavailable when there is anything to execute; every other
// endpoint is unaffected.
func Handler() http.Handler {
	return HandlerWithProvider(nil)
}

// HandlerWithProvider returns the HTTP surface with provider injected as the
// executor for POST /v1/apply. Passing a nil Provider keeps the read-only
// surface fully usable while apply reports provider_unavailable for non-empty
// plans. The service never persists changes itself; provider is the only
// component that executes them. Without a state file the state endpoints
// report state_unavailable.
func HandlerWithProvider(provider Provider) http.Handler {
	return newMux(provider, nil)
}

// HandlerWithProviderAndStateFile returns the full HTTP surface backed by the
// state file at path: GET /v1/state reports the stored revision and state,
// and POST /v1/state/apply plans against the file and commits the evolved
// state atomically under a non-blocking exclusive lock. When provider also
// implements Observer, GET /v1/state/drift compares the stored state against
// the observed remote snapshots without changing anything, and
// POST /v1/state/reconcile converges the remote toward the stored state
// without writing or bumping the revision; without an Observer those
// endpoints report observer_unavailable. The request/response behavior of
// every other endpoint is identical to HandlerWithProvider.
func HandlerWithProviderAndStateFile(provider Provider, path string) http.Handler {
	return newMux(provider, newStateBackend(path))
}

func newMux(provider Provider, backend *stateBackend) http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("/v1/configurations/validate", handleValidateConfiguration)
	mux.HandleFunc("/v1/configurations/order", handleOrderConfiguration)
	mux.HandleFunc("/v1/plans", handlePlan)
	mux.HandleFunc("/v1/apply", handleApply(provider))
	if backend != nil {
		mux.HandleFunc("/v1/state", backend.handleRead)
		mux.HandleFunc("/v1/state/apply", backend.handleApply(provider))
		mux.HandleFunc("/v1/state/drift", backend.handleDrift(observerOf(provider)))
		mux.HandleFunc("/v1/state/reconcile", backend.handleReconcile(provider, observerOf(provider)))
	} else {
		mux.HandleFunc("/v1/state", handleStateUnavailable)
		mux.HandleFunc("/v1/state/apply", handleStateUnavailable)
		mux.HandleFunc("/v1/state/drift", handleStateUnavailable)
		mux.HandleFunc("/v1/state/reconcile", handleStateUnavailable)
	}
	mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			w.Header().Set("Allow", http.MethodGet)
			http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
			return
		}
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "stackweaver", Version: Version})
	})
	return mux
}

package server

import "context"

// Snapshot is the normalized view of one resource on one side of a change:
// before for the prior state, after for the desired configuration.
type Snapshot struct {
	Type       string         `json:"type"`
	Properties map[string]any `json:"properties"`
	DependsOn  []string       `json:"dependsOn"`
}

// ChangeRequest is one ordered, already planned change handed to a Provider.
// Create carries only After, delete only Before, update carries both.
//
// Context carries the inbound request context and must not be retained past
// the Apply call; the server never persists the request itself.
type ChangeRequest struct {
	Context context.Context `json:"-"`
	Action  string          `json:"action"`
	Address string          `json:"address"`
	Before  *Snapshot       `json:"before,omitempty"`
	After   *Snapshot       `json:"after,omitempty"`
}

// Provider executes single planned changes. An implementation applies exactly
// the one change in the request and returns its outcome as an error; the
// server performs no persistence of its own and never rolls changes back.
type Provider interface {
	// Apply executes one planned change. A non-nil error stops the apply
	// run immediately; its text is reported verbatim to the caller.
	Apply(req ChangeRequest) error
}

// Observer is an optional capability a Provider may additionally implement to
// support read-only drift detection. The server only ever reads through an
// Observer; it never applies changes, writes state, or retains the context.
type Observer interface {
	// Observe reads the remote view of the managed resource at address.
	// The passed context is the inbound request context, handed over
	// unchanged. A nil snapshot with a nil error reports that the resource
	// does not exist remotely; a non-nil error stops the drift run
	// immediately and its text is reported verbatim to the caller.
	Observe(ctx context.Context, address string) (*Snapshot, error)
}

package server

import (
	"encoding/json"
	"fmt"
	"net/http"
	"sort"
)

// Error code reported when an apply run has changes to execute but no
// Provider was injected, and when a Provider rejects a change.
const (
	codeProviderUnavailable = "provider_unavailable"
	codeProviderError       = "provider_error"
)

type stateDocument struct {
	Resources []stateResource `json:"resources"`
}

// stateResource is one entry of the state document returned by an apply run.
type stateResource struct {
	Address    string         `json:"address"`
	Type       string         `json:"type"`
	Properties map[string]any `json:"properties"`
	DependsOn  []string       `json:"dependsOn"`
}

type applyResponse struct {
	Valid   bool              `json:"valid"`
	Errors  []validationError `json:"errors"`
	Applied *[]planChange     `json:"applied,omitempty"`
	Summary planSummary       `json:"summary"`
	State   *stateDocument    `json:"state,omitempty"`
}

// handleApply validates and plans a request exactly like POST /v1/plans, then
// hands the ordered non-noop changes to provider one at a time. It returns a
// handler so the injected Provider is captured once at wiring time.
func handleApply(provider Provider) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		if r.Method != http.MethodPost {
			rejectMethodNotAllowed(w)
			return
		}

		changes, summary, priorResources, ok := preparePlan(w, r)
		if !ok {
			// preparePlan already wrote the 400/422 response; a Provider is
			// never called for an invalid request.
			return
		}

		if len(changes) > 0 && provider == nil {
			w.WriteHeader(http.StatusServiceUnavailable)
			_ = json.NewEncoder(w).Encode(applyResponse{
				Valid: false,
				Errors: []validationError{{
					Code:    codeProviderUnavailable,
					Message: "apply requires a provider, but none is configured",
					Path:    "",
				}},
				Summary: summary,
			})
			return
		}

		// State starts from priorState and is mutated only as changes
		// succeed; the service holds it for this request alone.
		state := seedState(priorResources)
		applied := []planChange{}

		for i, change := range changes {
			// computePlan only emits create/update/delete; noops are absent
			// from the list, so a Provider is never invoked for them.
			req := ChangeRequest{
				Context: r.Context(),
				Action:  change.Action,
				Address: change.Address,
				Before:  change.Before,
				After:   change.After,
			}
			if err := provider.Apply(req); err != nil {
				// Stop immediately: later changes are skipped, earlier ones
				// are not rolled back.
				w.WriteHeader(http.StatusBadGateway)
				_ = json.NewEncoder(w).Encode(applyResponse{
					Valid:   false,
					Errors:  []validationError{{Code: codeProviderError, Message: err.Error(), Path: fmt.Sprintf("/changes/%d", i)}},
					Applied: &applied,
					Summary: summary,
					State:   renderState(state),
				})
				return
			}
			applied = append(applied, change)
			applyToState(state, change)
		}

		w.WriteHeader(http.StatusOK)
		_ = json.NewEncoder(w).Encode(applyResponse{
			Valid:   true,
			Errors:  []validationError{},
			Applied: &applied,
			Summary: summary,
			State:   renderState(state),
		})
	}
}

// seedState copies the validated prior-state resources into an addressable
// map that accumulates the effects of a run. Entries are normalized through
// snapshotOf so the output document is uniform: dependencies are sorted and
// always present, exactly like the after snapshots of successful changes.
func seedState(resources []planResource) map[string]planResource {
	state := make(map[string]planResource, len(resources))
	for _, resource := range resources {
		snap := snapshotOf(resource)
		state[resource.address] = planResource{
			address:    resource.address,
			typ:        snap.Type,
			properties: snap.Properties,
			dependsOn:  snap.DependsOn,
		}
	}
	return state
}

// applyToState records one successfully applied change: create and update
// adopt after, delete removes the address.
func applyToState(state map[string]planResource, change planChange) {
	switch change.Action {
	case "create", "update":
		state[change.Address] = planResource{
			address:    change.Address,
			typ:        change.After.Type,
			properties: change.After.Properties,
			dependsOn:  change.After.DependsOn,
		}
	case "delete":
		delete(state, change.Address)
	}
}

// renderState serializes the working state as an address-sorted document.
// Addresses are ordered by Unicode code point, which matches Go's byte-wise
// string comparison for UTF-8.
func renderState(state map[string]planResource) *stateDocument {
	addresses := make([]string, 0, len(state))
	for address := range state {
		addresses = append(addresses, address)
	}
	sort.Strings(addresses)

	resources := make([]stateResource, 0, len(addresses))
	for _, address := range addresses {
		resource := state[address]
		dependsOn := resource.dependsOn
		if dependsOn == nil {
			dependsOn = []string{}
		}
		resources = append(resources, stateResource{
			Address:    address,
			Type:       resource.typ,
			Properties: resource.properties,
			DependsOn:  dependsOn,
		})
	}
	return &stateDocument{Resources: resources}
}

